INSERT INTO questions (questionnaire_id, position, question_code, text, hint, type, options_json, is_required, max_choices, correct_answer_json)
SELECT q.id, v.position, v.question_code, v.text, v.hint, v.type, v.options_json::jsonb, v.is_required, v.max_choices::integer, v.correct_answer_json::jsonb
FROM questionnaires q
CROSS JOIN (VALUES
(1, 'ai_frequency', 'Как часто используете AI сейчас?', NULL, 'SINGLE_CHOICE',
 '["Не использую","Пробовал несколько раз","Использую время от времени","Использую каждую неделю","Использую почти ежедневно"]', true, NULL::text, NULL::text),
(2, 'ai_tasks', 'Для каких задач используете AI?', 'Можно выбрать несколько вариантов', 'MULTIPLE_CHOICE',
 '["Тексты и контент","Изображения и дизайн","Видео","Продажи и маркетинг","Аналитика","Автоматизация","Создание сайтов и приложений","Работа с документами","Пока не применяю","Другое"]', true, NULL, NULL),
(3, 'ai_result', 'Какой практический результат получили?', NULL, 'SINGLE_CHOICE',
 '["Пока никакого","Сэкономил время","Улучшил качество работы","Сделал учебный проект","Применил в рабочей задаче","Выполнил задачу для клиента","Получил доход с помощью AI"]', true, NULL, NULL),
(4, 'fin_projects', 'Какие проекты создали за время обучения?', 'Перечислите основные работы', 'LONG_TEXT', NULL, true, NULL, NULL),
(5, 'fin_projects_count', 'Сколько готовых проектов у вас получилось?', NULL, 'SINGLE_CHOICE',
 '["Ни одного","Один","2–3","4 и более"]', true, NULL, NULL),
(6, 'fin_work_applied', 'Применяли ли AI в работе или бизнесе?', NULL, 'SINGLE_CHOICE',
 '["Нет","Пробовал точечно","Регулярно применяю в работе","Внедрил в процессы бизнеса"]', true, NULL, NULL),
(7, 'fin_client_tasks', 'Выполняли ли задачи для клиентов?', NULL, 'SINGLE_CHOICE',
 '["Нет","Одну задачу","Несколько задач","Работаю с клиентами регулярно"]', true, NULL, NULL),
(8, 'ai_self_score', 'Оцените навыки работы с AI от 1 до 10', '1 — совсем не умею, 10 — уверенно применяю', 'SCALE', '{"min":1,"max":10}', true, NULL, NULL),
(9, 'fin_goal_reached', 'Насколько достигнута первоначальная цель?', NULL, 'SINGLE_CHOICE',
 '["Не достигнута","Частично","В основном","Полностью","Превзойдена"]', true, NULL, NULL),
(10, 'fin_task_solved', 'Удалось ли решить исходную задачу?', NULL, 'SINGLE_CHOICE',
 '["Нет","Частично","Да","Да, и пошёл дальше"]', true, NULL, NULL),
(11, 'fin_main_result', 'Опишите главный результат обучения', NULL, 'LONG_TEXT', NULL, true, NULL, NULL),
(12, 'fin_changes', 'Что изменилось в работе или бизнесе?', NULL, 'LONG_TEXT', NULL, false, NULL, NULL),
(13, 'fin_next', 'Что планируете делать дальше?', NULL, 'LONG_TEXT', NULL, false, NULL, NULL),
(14, 'fin_satisfaction', 'Итоговая удовлетворённость программой', '1 — совсем не доволен, 10 — полностью доволен', 'SCALE', '{"min":1,"max":10}', true, NULL, NULL),
(15, 'test_1', 'Что сильнее всего влияет на качество ответа текстовой AI-модели?', NULL, 'TEST_SINGLE_CHOICE',
 '["Ясная задача, контекст, ограничения и формат","Длина запроса","Вежливость формулировки","Количество попыток"]', true, NULL, '"Ясная задача, контекст, ограничения и формат"'),
(16, 'test_2', 'Что делать, если уверенный ответ AI содержит важный факт?', NULL, 'TEST_SINGLE_CHOICE',
 '["Проверить по надёжному источнику","Сразу использовать — модель уверена","Переспросить ту же модель","Ничего, факты всегда верны"]', true, NULL, '"Проверить по надёжному источнику"'),
(17, 'test_3', 'Какой промпт полезнее для бизнес-задачи?', NULL, 'TEST_SINGLE_CHOICE',
 '["Промпт с целью, аудиторией, контекстом, форматом и ограничениями","Максимально короткий промпт","Промпт из одного ключевого слова","Промпт на английском языке"]', true, NULL, '"Промпт с целью, аудиторией, контекстом, форматом и ограничениями"'),
(18, 'test_4', 'Для чего особенно полезна генерация изображений?', NULL, 'TEST_SINGLE_CHOICE',
 '["Визуальные концепты, креативы, иллюстрации и прототипы","Только для развлечения","Для замены фотографа во всех задачах","Для точных технических чертежей"]', true, NULL, '"Визуальные концепты, креативы, иллюстрации и прототипы"'),
(19, 'test_5', 'Что означает автоматизация AI-задачи?', NULL, 'TEST_SINGLE_CHOICE',
 '["Связать триггер, данные, AI-обработку и действие","Писать запросы быстрее","Использовать несколько моделей сразу","Купить платную подписку"]', true, NULL, '"Связать триггер, данные, AI-обработку и действие"'),
(20, 'test_6', 'Какой признак показывает практическую ценность AI?', NULL, 'TEST_SINGLE_CHOICE',
 '["Экономия времени или денег либо улучшение результата","Красивый интерфейс сервиса","Популярность инструмента","Количество сгенерированных вариантов"]', true, NULL, '"Экономия времени или денег либо улучшение результата"'),
(21, 'test_7', 'Что важнее для первого заработка на AI-услуге?', NULL, 'TEST_SINGLE_CHOICE',
 '["Решить конкретную проблему клиента и показать результат","Знать максимум инструментов","Иметь платные подписки","Сделать красивое портфолио без заказов"]', true, NULL, '"Решить конкретную проблему клиента и показать результат"')
) AS v(position, question_code, text, hint, type, options_json, is_required, max_choices, correct_answer_json)
WHERE q.type = 'final'
  AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.questionnaire_id = q.id);
